#!/usr/bin/env node
import { existsSync, readFileSync, readlinkSync } from 'node:fs';
import { join, resolve } from 'node:path';

import {
  assertAllowedPath,
  fail,
  fileInfo,
  parseArgs,
  printHelpAndExit,
  readJson,
  run,
} from './lib.mjs';

const HELP = [
  '--manifest <file>        release manifest generated by release-manifest.mjs (required)',
  '--unit-prefix <prefix>   systemd unit prefix (default: moyu-m6c)',
  '--release-root <dir>     optional immutable release root to compare with /proc/<pid>/cwd',
  '--api-url <url>          API health URL (default: http://127.0.0.1:4310)',
  '--supervisor-url <url>   supervisor health base (default: http://127.0.0.1:4491)',
  '--supervisor-token-file <file>  machine token file for the supervisor health check',
  '--allow-dirty            verify a diagnostic manifest (release gate refuses dirty)',
  '--help                   show this help without reading /proc or contacting services',
];

const { values } = parseArgs(process.argv.slice(2));
if (values.help)
  printHelpAndExit('Verify the three running MoYu services against one manifest', HELP, [
    'node scripts/m6c/verify-running.mjs --manifest docs/evidence/m6c/RUN/release-manifest.json --unit-prefix moyu-m6c',
  ]);

if (!values.manifest) fail('verify-running: --manifest is required', 2);
const manifestPath = assertAllowedPath(resolve(String(values.manifest)), 'manifest');
const manifest = readJson(manifestPath);
if (manifest.source?.dirty && values['allow-dirty'] !== true) {
  fail('verify-running: manifest is dirty; a release gate needs a clean source manifest', 1);
}
const prefix = String(values['unit-prefix'] ?? 'moyu-m6c');
const releaseRoot = values['release-root']
  ? assertAllowedPath(resolve(String(values['release-root'])), 'release root')
  : null;
const expected = {
  api: 'apps/api/dist/server.js',
  supervisor: 'apps/supervisor/dist/main.js',
  dispatcher: 'apps/dispatcher/dist/main.js',
};

const lines = [];
const results = [];
let failed = false;
for (const [name, entry] of Object.entries(expected)) {
  const unit = `${prefix}-${name}.service`;
  const shown = run('systemctl', [
    'show',
    unit,
    '-p',
    'MainPID',
    '-p',
    'ActiveState',
    '-p',
    'ExecStart',
    '-p',
    'WorkingDirectory',
    '-p',
    'User',
    '-p',
    'FragmentPath',
    '--no-pager',
  ]).stdout;
  const valuesMap = Object.fromEntries(
    shown
      .split('\n')
      .filter((line) => line.includes('='))
      .map((line) => [line.slice(0, line.indexOf('=')), line.slice(line.indexOf('=') + 1)]),
  );
  const pid = Number(valuesMap.MainPID ?? 0);
  const active = valuesMap.ActiveState ?? 'unknown';
  const problems = [];
  if (active !== 'active') problems.push(`ActiveState=${active}`);
  if (!Number.isInteger(pid) || pid <= 1) problems.push('MainPID is not a live process');
  let cwd = null;
  let cmdline = '';
  let artifact = null;
  if (pid > 1) {
    try {
      cwd = readlinkSync(`/proc/${pid}/cwd`);
    } catch {
      problems.push(`/proc/${pid}/cwd is unreadable`);
    }
    try {
      cmdline = readFileSync(`/proc/${pid}/cmdline`, 'utf8').replaceAll('\0', ' ').trim();
    } catch {
      problems.push(`/proc/${pid}/cmdline is unreadable`);
    }
    if (!cmdline.includes(entry)) problems.push(`cmdline does not contain ${entry}`);
    if (cwd) {
      const artifactPath = join(cwd, entry);
      if (!existsSync(artifactPath)) {
        problems.push(`artifact is missing under cwd: ${artifactPath}`);
      } else {
        artifact = fileInfo(artifactPath).sha256;
        if (manifest.artifacts?.[entry] !== artifact) {
          problems.push(
            `artifact hash ${artifact} != manifest ${manifest.artifacts?.[entry] ?? 'missing'}`,
          );
        }
      }
      if (releaseRoot && resolve(cwd) !== resolve(releaseRoot)) {
        problems.push(`cwd ${cwd} != release root ${releaseRoot}`);
      }
      const releaseManifest = join(cwd, 'release-manifest.json');
      if (existsSync(releaseManifest)) {
        try {
          const embedded = readJson(releaseManifest);
          if (embedded.source?.gitHead !== manifest.source?.gitHead) {
            problems.push('release release-manifest.json has a different gitHead');
          }
        } catch {
          problems.push('release release-manifest.json is unreadable');
        }
      }
    }
  }
  const line = {
    service: name,
    unit,
    pid,
    active,
    cwd,
    artifact,
    expectedArtifact: manifest.artifacts?.[entry] ?? null,
    user: valuesMap.User || '(default)',
    fragment: valuesMap.FragmentPath ?? null,
    cmdline,
    ok: problems.length === 0,
    problems,
  };
  results.push(line);
  if (!line.ok) failed = true;
  lines.push(
    `${name.padEnd(10)} pid=${String(pid).padEnd(8)} active=${active.padEnd(8)} cwd=${cwd ?? '-'} hash=${artifact ?? '-'} ${line.ok ? 'OK' : `FAIL: ${problems.join('; ')}`}`,
  );
}

if (values['api-url'] !== 'false') {
  const apiUrl = String(values['api-url'] ?? 'http://127.0.0.1:4310').replace(/\/+$/, '');
  try {
    const response = await fetch(`${apiUrl}/readyz`, { signal: AbortSignal.timeout(8000) });
    const body = await response.text();
    if (response.status !== 200) {
      failed = true;
      lines.push(`api/readyz FAIL HTTP ${response.status}: ${body.slice(0, 200)}`);
    } else {
      lines.push(`api/readyz OK HTTP 200 ${body.slice(0, 200)}`);
    }
  } catch (error) {
    failed = true;
    lines.push(`api/readyz FAIL ${error instanceof Error ? error.message : String(error)}`);
  }
}

if (values['supervisor-url'] !== 'false') {
  const supervisorUrl = String(values['supervisor-url'] ?? 'http://127.0.0.1:4491').replace(
    /\/+$/,
    '',
  );
  const tokenFile = values['supervisor-token-file']
    ? assertAllowedPath(resolve(String(values['supervisor-token-file'])), 'supervisor token file')
    : null;
  try {
    const token = tokenFile ? readFileSync(tokenFile, 'utf8').trim() : '';
    const response = await fetch(`${supervisorUrl}/control/v1/health`, {
      headers: token ? { authorization: `Bearer ${token}` } : {},
      signal: AbortSignal.timeout(8000),
    });
    const body = await response.text();
    const expectedStatus = token ? 200 : 401;
    if (response.status !== expectedStatus) {
      failed = true;
      lines.push(`supervisor/health FAIL HTTP ${response.status} (expected ${expectedStatus})`);
    } else {
      lines.push(`supervisor/health OK HTTP ${response.status} ${body.slice(0, 200)}`);
    }
  } catch (error) {
    failed = true;
    lines.push(`supervisor/health FAIL ${error instanceof Error ? error.message : String(error)}`);
  }
}

process.stdout.write(`${lines.join('\n')}\n`);
process.stdout.write(
  `${JSON.stringify({ manifest: manifestPath, gitHead: manifest.source?.gitHead, results, failed })}\n`,
);
process.exit(failed ? 1 : 0);
